"""JWT session management for Noko."""

from datetime import datetime, timedelta, timezone
from uuid import uuid4

import jwt
from sqlalchemy import select

from src.config import settings

ALGORITHM = "HS256"


class InvalidTokenError(Exception):
    """Raised when a token is expired, malformed, or tampered with."""


def create_token(
    family_id: str,
    member_id: str,
    role: str,
    token_version: int = 1,
    expires_minutes: int = 60,
) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "family_id": family_id,
        "member_id": member_id,
        "role": role,
        "token_version": token_version,
        "iat": now,
        "exp": now + timedelta(minutes=expires_minutes),
    }
    return jwt.encode(payload, settings.secret_key, algorithm=ALGORITHM)


def verify_token(token: str) -> dict:
    try:
        return jwt.decode(token, settings.secret_key, algorithms=[ALGORITHM])
    except jwt.PyJWTError as e:
        raise InvalidTokenError(str(e)) from e


def create_magic_link_token(email: str, expires_minutes: int = 15) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "email": email,
        "purpose": "magic_link",
        "jti": str(uuid4()),
        "iat": now,
        "exp": now + timedelta(minutes=expires_minutes),
    }
    return jwt.encode(payload, settings.secret_key, algorithm=ALGORITHM)


def verify_magic_link_token(token: str) -> dict:
    claims = verify_token(token)
    if claims.get("purpose") != "magic_link":
        raise InvalidTokenError("Not a magic link token")
    return claims


def create_invite_token(
    family_id: str,
    role: str,
    intended_email: str | None = None,
    expires_hours: int = 24,
) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "family_id": family_id,
        "role": role,
        "purpose": "invite",
        "jti": str(uuid4()),
        "iat": now,
        "exp": now + timedelta(hours=expires_hours),
    }
    if intended_email is not None:
        payload["intended_email"] = intended_email
    return jwt.encode(payload, settings.secret_key, algorithm=ALGORITHM)


def verify_invite_token(token: str) -> dict:
    claims = verify_token(token)
    if claims.get("purpose") != "invite":
        raise InvalidTokenError("Not an invite token")
    return claims


def create_family_select_token(email: str, expires_minutes: int = 5) -> str:
    """Short-lived token for multi-family users to select which family to enter."""
    now = datetime.now(timezone.utc)
    payload = {
        "email": email,
        "purpose": "family_select",
        "jti": str(uuid4()),
        "iat": now,
        "exp": now + timedelta(minutes=expires_minutes),
    }
    return jwt.encode(payload, settings.secret_key, algorithm=ALGORITHM)


def verify_family_select_token(token: str) -> dict:
    claims = verify_token(token)
    if claims.get("purpose") != "family_select":
        raise InvalidTokenError("Not a family select token")
    return claims


async def bump_token_version(db, member_id: str) -> None:
    """Increment a member's token_version, invalidating all outstanding JWTs.

    Call this when a member's role changes or when they are removed from a family.
    Caller must commit the session.
    """
    from src.models import Member  # deferred to avoid circular import

    result = await db.execute(select(Member).where(Member.id == member_id))
    member = result.scalar_one_or_none()
    if member is not None:
        member.token_version += 1

"""Member resolution and handler dispatch."""

from datetime import UTC, datetime

from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession

from src.models import Member
from src.rate_limit import webhook_limiter

# Shared with invites.py — token_hex(LINKING_CODE_LENGTH // 2) produces this many hex chars
LINKING_CODE_LENGTH = 12

# Per-member rate limit: 10 messages per 1 minute
WEBHOOK_MAX_MESSAGES = 10
WEBHOOK_WINDOW_SECONDS = 60

RATE_LIMIT_MESSAGE = (
    "You're sending messages too quickly. Please slow down and try again in a minute."
)


async def resolve_member(db: AsyncSession, chat_id: str) -> Member | None:
    result = await db.execute(select(Member).where(Member.telegram_chat_id == chat_id))
    return result.scalar_one_or_none()


CHAT_ID_ALREADY_LINKED_MESSAGE = (
    "This Telegram account is already linked to another member. "
    "Ask a parent to unlink it from the dashboard first."
)


async def try_link_by_code(
    db: AsyncSession, chat_id: str, text: str
) -> tuple[Member | None, str | None]:
    """If text matches a valid, unexpired linking code, save chat_id and return member.

    Returns (member, None) on success, (None, error_msg) if chat_id is already
    linked to another member, or (None, None) if the code doesn't match.
    """
    code = text.strip()
    if len(code) != LINKING_CODE_LENGTH:
        return None, None
    result = await db.execute(select(Member).where(Member.linking_code == code))
    member = result.scalars().first()
    if not member:
        return None, None
    if member.linking_code_expires_at is None:
        return None, None
    # Compare as naive UTC — column is TIMESTAMP WITHOUT TIME ZONE
    if datetime.now(UTC).replace(tzinfo=None) > member.linking_code_expires_at:
        return None, None
    # Check if this chat_id is already linked to another member
    existing = await db.execute(
        select(Member).where(Member.telegram_chat_id == chat_id)
    )
    if existing.scalars().first() is not None:
        return None, CHAT_ID_ALREADY_LINKED_MESSAGE
    member.telegram_chat_id = chat_id
    member.linking_code = None
    member.linking_code_expires_at = None
    await db.flush()
    return member, None


def _check_rate_limit(member_id) -> bool:
    """Return True if member is within rate limits, False if throttled."""
    return webhook_limiter.is_allowed(
        f"webhook:{member_id}",
        max_requests=WEBHOOK_MAX_MESSAGES,
        window_seconds=WEBHOOK_WINDOW_SECONDS,
    )


def _should_send_rate_limit_reply(member_id) -> bool:
    """Return True only for the first rejection in a window, to avoid reply spam."""
    return webhook_limiter.is_allowed(
        f"webhook_reply:{member_id}",
        max_requests=1,
        window_seconds=WEBHOOK_WINDOW_SECONDS,
    )


class HandlerRegistry:
    def __init__(self):
        self._handlers: dict[str, object] = {}

    def register(self, msg_type: str, handler):
        self._handlers[msg_type] = handler

    def unregister(self, msg_type: str):
        self._handlers.pop(msg_type, None)

    def get(self, msg_type: str):
        return self._handlers.get(msg_type)


async def dispatch(
    db: AsyncSession, tg_client, update: dict, registry: HandlerRegistry
):
    """Parse update type, resolve member, call handler."""

    # Callback query
    if "callback_query" in update:
        cq = update["callback_query"]
        chat_id = str(cq.get("from", {}).get("id", ""))
        member = await resolve_member(db, chat_id)
        if not member:
            await tg_client.send_message(chat_id, "Sorry, I don't know you.")
            return
        if not _check_rate_limit(member.id):
            if _should_send_rate_limit_reply(member.id):
                await tg_client.send_message(chat_id, RATE_LIMIT_MESSAGE)
            return
        handler = registry.get("callback_query")
        if handler:
            await handler(db, tg_client, member, cq)
        return

    # Message (text or photo)
    message = update.get("message")
    if not message:
        return

    chat_id = str(message.get("chat", {}).get("id", ""))
    member = await resolve_member(db, chat_id)
    if not member:
        # Try linking code handshake
        text = message.get("text", "")
        if text:
            member, error = await try_link_by_code(db, chat_id, text)
            if error:
                await tg_client.send_message(chat_id, error)
                return
        if member:
            await tg_client.send_message(
                chat_id, f"Welcome, {member.name}! You're all set."
            )
            return
        await tg_client.send_message(chat_id, "Sorry, I don't know you.")
        return

    # Per-member rate limiting — after resolution, before AI dispatch
    if not _check_rate_limit(member.id):
        if _should_send_rate_limit_reply(member.id):
            await tg_client.send_message(chat_id, RATE_LIMIT_MESSAGE)
        return

    if "photo" in message:
        handler = registry.get("photo")
        if handler:
            await handler(db, tg_client, member, message)
    elif "text" in message:
        handler = registry.get("text")
        if handler:
            await handler(db, tg_client, member, message)

