/**
 * Noko API client — fetch wrapper with JWT auth header injection.
 */

// When served from /dashboard, API is on the same origin at root.
// When served separately, override with window.NOKO_API_BASE.
const API_BASE = window.NOKO_API_BASE || window.location.origin;

function getToken() {
  return localStorage.getItem('noko_token');
}

function setToken(token) {
  localStorage.setItem('noko_token', token);
}

function clearToken() {
  localStorage.removeItem('noko_token');
}

function isAuthenticated() {
  return !!getToken();
}

async function apiFetch(path, opts = {}) {
  const token = getToken();
  const headers = { ...(opts.headers || {}) };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }
  if (opts.body) {
    headers['Content-Type'] = headers['Content-Type'] || 'application/json';
  }

  const res = await fetch(`${API_BASE}${path}`, { ...opts, headers });

  if (res.status === 401) {
    clearToken();
    window.dispatchEvent(new CustomEvent('noko:logout'));
    throw new Error('Session expired');
